{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_dist = case["core_distance"]
    distances = case["distances"]

    # Compute mutual reachability distance for each pair:
    # mrd(u, v) = max(core_dist[u], core_dist[v], dist(u, v))
    mrd_edges = []
    for entry in distances:
        u, v, d = entry[0], entry[1], entry[2]
        mrd = max(core_dist[u], core_dist[v], d)
        mrd_edges.append((mrd, u, v))

    # Sort edges by mutual reachability distance (Kruskal's MST)
    mrd_edges.sort(key=lambda e: e[0])

    # Union-Find with path compression and union by rank
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    mst_edges = []
    for mrd, u, v in mrd_edges:
        if union(u, v):
            a, b = (u, v) if u <= v else (v, u)
            mst_edges.append([a, b, mrd])

    # Return edges sorted by weight, then by node names for determinism
    mst_edges.sort(key=lambda e: (e[2], e[0], e[1]))

    return {"mst_edges": mst_edges}
